<script setup>
import WbProductImages from "../../components/WbProductImages.vue";
import WbCardLimits from "../../components/listing/WbCardLimits.vue";
import { WB_REMOTE_WRITES_ENABLED } from "../../../../src/shared/wb-capabilities.js";
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElMessage } from 'element-plus';
import { apiClient, currentApiCacheScope } from '../../utils/api.js';
import {shanghaiDateTimeText} from '../../utils/shanghai-date.js';
import MarketplaceBadge from '../../components/MarketplaceBadge.vue';
import {useAuthStore} from '../../stores/auth.js';
import {hasPermission} from '../../../../src/shared/permissions.js';
import {wbKnownNumber,wbOnlineStatus,wbOnlineSizes,wbOnlineSizeLabel,wbOnlineMapping,wbOnlineSizePrice,wbOnlineWeightGrams,wbLocalInventoryPackage} from '../../utils/wb-online-products.js';

const router=useRouter();
const route=useRoute(),shops=ref([]),shopId=ref(null),rows=ref([]),loading=ref(false),busy=ref(false),search=ref(''),status=ref('all'),page=ref(1),notice=ref('');
const auth=useAuthStore(),canManageInventory=computed(()=>hasPermission(auth.user,'inventory.write'));
let productRequest=0;
const editor=reactive({visible:false,card:null,subject:null,attributes:[],values:{},categories:[],categorySearch:'',barcodes:''});
const binding=reactive({visible:false,row:null,shop:null,chrt:null,product:null,options:[],search:''});
const creation=reactive({visible:false,row:null,shop:null,chrt:null,name:'',length_cm:null,width_cm:null,height_cm:null,package_weight_g:null});
const creationReady=computed(()=>creation.chrt&&creation.name.trim()&&['length_cm','width_cm','height_cm','package_weight_g'].every(key=>wbKnownNumber(creation[key])>0));
const media=reactive({visible:false,row:null,urls:''});
const pricing=reactive({visible:false,row:null,price:1,discount:0,task:null,result:null});
const stock=reactive({visible:false,row:null,chrt:null,quantity:0,available:0,current:null});
async function loadStock(){await run(async scope=>{const value=await apiClient.get(`/api/wb/stocks?shop_id=${selected()}&nm_id=${stock.row.nm_id}&chrt_id=${stock.chrt}`,{noCache:true});if(scope!==currentApiCacheScope())return;stock.available=value.available;stock.current=value.stocks?.[0]?.amount??null;stock.quantity=0;});}
async function saveStock(){await run(async scope=>{const value=await apiClient.post('/api/wb/stocks/set',{shop_id:selected(),nm_id:stock.row.nm_id,chrt_id:stock.chrt,quantity:stock.quantity});if(scope===currentApiCacheScope()){notice.value=value.message;stock.visible=false;}});}
const priceText=(row,size)=>{const value=wbKnownNumber(wbOnlineSizePrice(row,size)?.price);return value===null?'未同步':`${value.toLocaleString('zh-CN')} ${row.price_info.currency||'币种未返回'}`;};
const stockFor=(row,size)=>wbKnownNumber(row.stock_info?.sizes?.find(item=>Number(item.chrt_id)===Number(size.chrtID))?.amount);
const unboundSizes=row=>wbOnlineSizes(row).filter(size=>!wbOnlineMapping(row,size));
const time=value=>value?shanghaiDateTimeText(value,{assumeUtcWhenNaive:true}):'未返回';
const errors=reactive({visible:false,rows:[]});
const filtered=computed(()=>rows.value.filter(row=>(status.value==='all'||row.online_status===status.value)&&[row.title,row.vendor_code,row.nm_id,...wbOnlineSizes(row).flatMap(size=>[size.chrtID,...(size.skus||[])])].some(value=>String(value||'').toLowerCase().includes(search.value.trim().toLowerCase()))));
const paged=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20));
function selected(){if(!shopId.value)throw new Error('请先选择 WB 店铺；还没有店铺时，请到企业店铺中添加 WB 授权。');return Number(shopId.value);}
async function run(work){const scope=currentApiCacheScope();if(busy.value)return;busy.value=true;try{await work(scope);}catch(error){if(scope===currentApiCacheScope()){notice.value='操作未完成：'+error.message;ElMessage.error(error.message);}}finally{if(scope===currentApiCacheScope())busy.value=false;}}
async function load(){const request=++productRequest,scope=currentApiCacheScope(),targetShop=Number(shopId.value);rows.value=[];page.value=1;loading.value=false;if(!shopId.value)return;loading.value=true;try{const result=await apiClient.get(`/api/wb/products?shop_id=${selected()}`,{noCache:true});if(request===productRequest&&scope===currentApiCacheScope()&&targetShop===Number(shopId.value))rows.value=result.rows||[];}catch(error){if(request===productRequest&&scope===currentApiCacheScope()&&targetShop===Number(shopId.value)){notice.value='商品读取失败：'+error.message;ElMessage.error(error.message);}}finally{if(request===productRequest&&scope===currentApiCacheScope()&&targetShop===Number(shopId.value))loading.value=false;}}
async function bootstrap(){const scope=currentApiCacheScope();try{const value=await apiClient.get('/api/wb/shops',{noCache:true});if(scope!==currentApiCacheScope())return;shops.value=value.filter(row=>row.status==='active');shopId.value=shops.value[0]?.id||null;await changeShop();if(WB_REMOTE_WRITES_ENABLED&&route.path==='/wb/listing'&&shopId.value)openEditor();}catch(error){ElMessage.error(error.message);}}
async function changeShop(){notice.value='';search.value='';status.value='all';for(const state of [binding,creation,editor,media,pricing,errors,stock])state.visible=false;await load();}
async function sync(row=null){await run(async scope=>{const target=selected(),result=await apiClient.post('/api/wb/products/refresh',{shop_id:target,...(row?{nm_id:Number(row.nm_id)}:{})});if(scope!==currentApiCacheScope()||target!==Number(shopId.value))return;notice.value=result.warnings?.length?result.warnings.join('；'):`已同步 WB 商品资料、价格和卖家仓库存。`;await load();});}
function openEditor(row){
  if(!shopId.value)return ElMessage.warning('请先配置并选择 WB 店铺。');
  const card=row?JSON.parse(JSON.stringify(row.card)):{title:'',vendorCode:'',brand:'',description:'',dimensions:{length:1,width:1,height:1,weightBrutto:0.1},characteristics:[],sizes:[{techSize:'0',skus:[]}]};
  Object.assign(editor,{visible:true,card,subject:card.subjectID||null,attributes:[],values:Object.fromEntries((card.characteristics||[]).map(item=>[item.id,(item.value||[]).join(', ')])),barcodes:(card.sizes||[]).flatMap(size=>size.skus||[]).join('\n')});
  if(editor.subject)loadAttributes();
}
async function searchCategories(){await run(async scope=>{const value=await apiClient.get(`/api/wb/categories?shop_id=${selected()}&search=${encodeURIComponent(editor.categorySearch)}`);if(scope===currentApiCacheScope())editor.categories=value.data||[];});}
async function loadAttributes(){try{const scope=currentApiCacheScope();const value=await apiClient.get(`/api/wb/characteristics?shop_id=${selected()}&subject_id=${editor.subject}`);if(scope===currentApiCacheScope())editor.attributes=value.data||[];}catch(error){ElMessage.error(error.message);}}
async function publish(){await run(async scope=>{
  const card=JSON.parse(JSON.stringify(editor.card));
  if(!card.nmID)card.sizes=[{techSize:'0',skus:editor.barcodes.split(/\s+/).filter(Boolean)}];
  card.characteristics=editor.attributes.map(item=>({id:item.charcID,value:String(editor.values[item.charcID]||'').split(/[,，]/).map(value=>value.trim()).filter(Boolean)})).filter(item=>item.value.length);
  const value=await apiClient.post('/api/wb/publish',{shop_id:selected(),subject_id:editor.subject,card});
  if(scope!==currentApiCacheScope())return;notice.value=value.message;editor.visible=false;
});}
async function showErrors(){await run(async scope=>{const value=await apiClient.get(`/api/wb/publish-errors?shop_id=${selected()}`,{noCache:true});if(scope!==currentApiCacheScope())return;errors.rows=value.data||value.cards||[];errors.visible=true;});}
function openBinding(row){Object.assign(binding,{visible:true,row,shop:selected(),chrt:unboundSizes(row)[0]?.chrtID||null,product:null,options:[],search:''});findProducts();}
async function findProducts(){await run(async scope=>{const target=binding.shop,result=await apiClient.get(`/api/products?inventory=1&paged=1&page=1&pageSize=30&search=${encodeURIComponent(binding.search)}`,{noCache:true});if(scope===currentApiCacheScope()&&target===Number(shopId.value)&&binding.visible)binding.options=Array.isArray(result)?result:result.rows||[];});}
async function bind(){await run(async scope=>{const target=binding.shop;await apiClient.post('/api/wb/products/bind',{shop_id:target,nm_id:binding.row.nm_id,chrt_id:binding.chrt,product_id:binding.product,vendor_code:binding.row.vendor_code});if(scope!==currentApiCacheScope()||target!==Number(shopId.value))return;binding.visible=false;await load();ElMessage.success('WB 规格已绑定到现有基础商品');});}
function inventoryName(){const size=wbOnlineSizes(creation.row).find(item=>Number(item.chrtID)===Number(creation.chrt));creation.name=[creation.row.title||creation.row.vendor_code,wbOnlineSizeLabel(size||{})==='通用'?'':wbOnlineSizeLabel(size)].filter(Boolean).join(' ');}
function openCreation(row){Object.assign(creation,{visible:true,row,shop:selected(),chrt:unboundSizes(row)[0]?.chrtID||null,name:'',...wbLocalInventoryPackage(row)});inventoryName();}
async function createInventory(){if(!creationReady.value)return;await run(async scope=>{const target=creation.shop;await apiClient.post('/api/wb/products/create-inventory',{shop_id:target,nm_id:creation.row.nm_id,chrt_id:creation.chrt,name:creation.name.trim(),length_cm:Number(creation.length_cm),width_cm:Number(creation.width_cm),height_cm:Number(creation.height_cm),package_weight_g:Number(creation.package_weight_g)});if(scope!==currentApiCacheScope()||target!==Number(shopId.value))return;creation.visible=false;await load();ElMessage.success('已创建本地库存产品并绑定 WB 规格');});}
async function saveMedia(){await run(async scope=>{const value=await apiClient.post('/api/wb/products/media',{shop_id:selected(),nm_id:media.row.nm_id,urls:media.urls.split(/\s+/).filter(Boolean)});if(scope!==currentApiCacheScope())return;media.visible=false;notice.value=value.message;});}
async function savePrice(){await run(async scope=>{const value=await apiClient.post('/api/wb/prices/set',{shop_id:selected(),nm_id:pricing.row.nm_id,price:pricing.price,discount:pricing.discount});if(scope!==currentApiCacheScope())return;pricing.task=value.upload_id;notice.value=value.message;});}
async function checkPrice(){await run(async scope=>{const value=await apiClient.get(`/api/wb/price-result?shop_id=${selected()}&upload_id=${pricing.task}`,{noCache:true});if(scope===currentApiCacheScope())pricing.result=value;});}
function resetScope(){productRequest++;shops.value=[];shopId.value=null;rows.value=[];notice.value='';for(const state of [editor,binding,creation,media,pricing,errors,stock])state.visible=false;busy.value=false;bootstrap();}
onMounted(()=>{bootstrap();window.addEventListener('erp:auth-scope-changed',resetScope);});
onBeforeUnmount(()=>{productRequest++;window.removeEventListener('erp:auth-scope-changed',resetScope);});
</script>
<template>
  <div class="wb-products-page">
    <div class="page-heading"><h2><MarketplaceBadge platform="wb"/> WB 在线商品</h2><div><WbCardLimits :shops="shops" :shop-id="Number(shopId)||null"/><el-button :loading="busy" :disabled="!shopId" @click="sync()">同步商品及库存</el-button><el-button type="primary" :disabled="!shopId" @click="router.push('/wb/listing')">模板与商品草稿</el-button></div></div>
    <el-alert v-if="!shops.length" title="尚未配置 WB 店铺" description="请由企业管理员到“企业店铺 → 新增店铺”，选择 WB（中国主体），填写 API 授权并绑定卖家仓。这里会展示真实店铺数据。" type="info" :closable="false"/>
    <el-alert v-if="notice" :title="notice" type="info" :closable="false"/>
    <div class="wb-filters"><el-select v-model="shopId" :disabled="busy" placeholder="选择 WB 店铺" @change="changeShop"><el-option v-for="shop in shops" :key="shop.id" :value="Number(shop.id)" :label="shop.name+(shop.environment==='sandbox'?'（沙箱）':'')"/></el-select><el-select v-model="status" placeholder="全部状态" @change="page=1"><el-option label="全部状态" value="all"/><el-option label="商品库" value="in_catalog"/><el-option label="WB 回收站" value="archived"/></el-select><el-input v-model="search" placeholder="搜索名称、货号、WB SKU 或条码" clearable @input="page=1"/><el-button :disabled="!shopId||busy" @click="showErrors">查看发布错误</el-button></div>
    <el-table v-loading="loading" :data="paged" stripe border class="erp-data-table" row-key="id" empty-text="暂无已同步的 WB 商品">
      <el-table-column label="店铺 / 状态" width="165" fixed="left"><template #default="{row}"><div class="cell-stack"><strong>{{row.shop_name||shops.find(shop=>Number(shop.id)===Number(row.shop_id))?.name||'未返回店铺'}}</strong><el-tag size="small" :type="row.online_status==='archived'?'info':'primary'">{{wbOnlineStatus(row)}}</el-tag></div></template></el-table-column>
      <el-table-column label="WB SKU / 条码" min-width="220"><template #default="{row}"><div class="cell-stack"><strong>WB 商品编号：{{row.nm_id||'未返回'}}</strong><div v-for="size in wbOnlineSizes(row)" :key="size.chrtID" class="size-block"><span>{{wbOnlineSizeLabel(size)}} · SKU（chrtID）{{size.chrtID||'未返回'}}</span><small>{{(size.skus||[]).join(' / ')||'未返回条码'}}</small></div></div></template></el-table-column>
      <el-table-column label="主图" width="105" align="center"><template #default="{row}"><WbProductImages :card="row.card"/></template></el-table-column>
      <el-table-column label="在线商品信息" min-width="300"><template #default="{row}"><div class="cell-stack"><strong>{{row.title||row.card.title||'未返回标题'}}</strong><span>货号：{{row.vendor_code||'未返回'}}</span><small>类目：{{row.card.subjectName||'未返回'}}<template v-if="row.card.subjectID">（{{row.card.subjectID}}）</template></small><small>品牌：{{row.card.brand||'未返回'}}</small><small>评分：{{wbKnownNumber(row.rating)??'未返回'}}</small></div></template></el-table-column>
      <el-table-column label="售价" min-width="165" align="right"><template #default="{row}"><div v-for="size in wbOnlineSizes(row)" :key="size.chrtID" class="size-block price-cell"><small v-if="wbOnlineSizes(row).length>1">{{wbOnlineSizeLabel(size)}} · {{size.chrtID}}</small><strong>{{priceText(row,size)}}</strong><small v-if="wbKnownNumber(wbOnlineSizePrice(row,size)?.original_price)!==null">原价 {{wbOnlineSizePrice(row,size).original_price}} {{row.price_info.currency||''}}</small></div><small v-if="!wbOnlineSizes(row).length">未同步</small><small v-if="row.price_info?.synced_at">{{time(row.price_info.synced_at)}}</small><small v-if="row.price_error" class="warning-text">{{row.price_error}}</small><el-button v-if="row.price_error||!row.price_info||wbOnlineSizes(row).some(size=>wbKnownNumber(wbOnlineSizePrice(row,size)?.price)===null)" link type="primary" :disabled="busy" @click="sync(row)">同步价格</el-button></template></el-table-column>
      <el-table-column label="绑定库存" min-width="235"><template #default="{row}"><div v-for="size in wbOnlineSizes(row)" :key="size.chrtID" class="size-block"><small>{{wbOnlineSizeLabel(size)}} · {{size.chrtID}}</small><template v-if="wbOnlineMapping(row,size)"><strong>{{wbOnlineMapping(row,size).product_name||'库存产品'}}</strong><span>{{wbOnlineMapping(row,size).inventory_number||wbOnlineMapping(row,size).product_code||'编号未返回'}}</span></template><span v-else class="muted-text">未绑定库存产品</span></div></template></el-table-column>
      <el-table-column label="FBS 库存" width="175" align="center"><template #default="{row}"><div class="cell-stack stock-cell"><strong class="stock-number" :class="{'is-zero-stock':wbKnownNumber(row.fbs_stock)===0}">{{wbKnownNumber(row.fbs_stock)??'未同步'}}</strong><small v-if="wbOnlineSizes(row).length>1" v-for="size in wbOnlineSizes(row)" :key="size.chrtID">{{wbOnlineSizeLabel(size)}}：{{stockFor(row,size)??'未同步'}}</small><small v-if="row.stock_synced_at">{{time(row.stock_synced_at)}}</small><small v-if="row.stock_error" class="warning-text">{{row.stock_error}}</small><el-button v-if="wbKnownNumber(row.fbs_stock)===null" link type="primary" :disabled="busy" @click="sync(row)">同步库存</el-button></div></template></el-table-column>
      <el-table-column label="上架时间（北京）" width="180"><template #default="{row}">{{time(row.published_at)}}</template></el-table-column>
      <el-table-column label="包装尺寸 / 重量" width="190"><template #default="{row}"><div>{{row.card.dimensions?.length??'—'}} × {{row.card.dimensions?.width??'—'}} × {{row.card.dimensions?.height??'—'}} cm</div><strong>{{wbOnlineWeightGrams(row)??'未返回'}}<template v-if="wbOnlineWeightGrams(row)!==null"> g</template></strong></template></el-table-column>
      <el-table-column label="最后同步（北京）" width="180"><template #default="{row}">{{time(row.synced_at)}}</template></el-table-column>
      <el-table-column v-if="canManageInventory||WB_REMOTE_WRITES_ENABLED" label="操作" width="205" fixed="right"><template #default="{row}"><div class="row-actions"><template v-if="canManageInventory"><el-button link type="primary" :disabled="busy||!unboundSizes(row).length" @click="openBinding(row)">绑定库存</el-button><el-button link type="primary" :disabled="busy||!unboundSizes(row).length" @click="openCreation(row)">创建库存</el-button></template><template v-if="WB_REMOTE_WRITES_ENABLED"><el-button link type="primary" @click="openEditor(row)">编辑</el-button><el-button link type="primary" @click="Object.assign(media,{visible:true,row,urls:(row.card.photos||[]).map(item=>item.big).filter(Boolean).join('\n')})">图片</el-button><el-button link type="primary" @click="Object.assign(stock,{visible:true,row,chrt:row.card.sizes?.[0]?.chrtID,current:null,available:0,quantity:0});loadStock()">库存</el-button><el-button link type="primary" @click="Object.assign(pricing,{visible:true,row,price:1,discount:0,task:null,result:null})">改价</el-button></template></div></template></el-table-column>
    </el-table>
    <el-pagination v-model:current-page="page" :page-size="20" :total="filtered.length" layout="total,prev,pager,next"/>

    <el-dialog v-model="editor.visible" :title="editor.card?.nmID?'编辑 WB 商品':'WB 商品上架'" width="min(960px,95vw)" destroy-on-close>
      <el-form v-if="editor.card" label-position="top" class="wb-editor">
        <el-form-item label="商品类目" required><div class="wb-filters"><el-input v-model="editor.categorySearch" placeholder="输入类目关键词"/><el-button :loading="busy" @click="searchCategories">查询类目</el-button><el-select v-model="editor.subject" :disabled="!!editor.card.nmID" placeholder="选择 WB 类目" @change="loadAttributes"><el-option v-for="item in editor.categories" :key="item.subjectID" :value="item.subjectID" :label="item.subjectName"/></el-select></div></el-form-item>
        <div class="wb-grid"><el-form-item label="商品标题" required><el-input v-model="editor.card.title" :maxlength="60"/></el-form-item><el-form-item label="商家货号" required><el-input v-model="editor.card.vendorCode"/></el-form-item><el-form-item label="品牌"><el-input v-model="editor.card.brand"/></el-form-item></div>
        <el-form-item label="商品描述"><el-input v-model="editor.card.description" type="textarea" :rows="4"/></el-form-item>
        <div class="wb-grid"><el-form-item v-for="(label,key) in {length:'包装长（cm）',width:'包装宽（cm）',height:'包装高（cm）',weightBrutto:'包装重量（kg）'}" :key="key" :label="label"><el-input-number v-model="editor.card.dimensions[key]" :min="0.001" :precision="3"/></el-form-item></div>
        <el-form-item v-if="!editor.card.nmID" label="商品条码（每行一个，当前新建通用规格）" required><el-input v-model="editor.barcodes" type="textarea"/></el-form-item>
        <el-divider>类目属性</el-divider><div class="wb-grid"><el-form-item v-for="attribute in editor.attributes" :key="attribute.charcID" :label="attribute.name" :required="attribute.required"><el-input v-model="editor.values[attribute.charcID]" placeholder="多个值用逗号分隔"/></el-form-item></div>
        <el-alert title="提交后由 WB 异步处理，不代表已上架。首次创建完成后，需同步商品，再上传图片、设置价格与库存。" type="info" :closable="false"/>
      </el-form><template #footer><el-button @click="editor.visible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!editor.subject" @click="publish">提交到 WB</el-button></template>
    </el-dialog>
    <el-dialog v-if="binding.visible" v-model="binding.visible" title="绑定 SKU 到库存产品" width="680px" destroy-on-close><el-form label-position="top"><el-form-item label="WB 规格" required><el-select v-model="binding.chrt" placeholder="选择要绑定的 WB 规格"><el-option v-for="size in wbOnlineSizes(binding.row)" :key="size.chrtID" :label="`${wbOnlineSizeLabel(size)} · ${size.chrtID}${wbOnlineMapping(binding.row,size)?'（已绑定）':''}`" :value="size.chrtID" :disabled="!!wbOnlineMapping(binding.row,size)"/></el-select></el-form-item><el-form-item label="搜索本地库存产品"><div class="binding-search"><el-input v-model="binding.search" placeholder="库存编号或产品名称" @keyup.enter="findProducts"/><el-button :loading="busy" @click="findProducts">搜索</el-button></div></el-form-item><el-form-item label="库存产品" required><el-select v-model="binding.product" filterable placeholder="选择现有库存产品"><el-option v-for="item in binding.options" :key="item.id" :value="Number(item.id)" :label="`${item.inventory_number||item.code||item.id} · ${item.name}`"/></el-select></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="binding.visible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!binding.product||!binding.chrt" @click="bind">保存绑定</el-button></template></el-dialog>
    <el-dialog v-if="creation.visible" v-model="creation.visible" title="根据 WB 商品创建库存" width="680px" destroy-on-close><el-form label-position="top"><el-form-item label="WB 规格" required><el-select v-model="creation.chrt" placeholder="选择要创建库存的 WB 规格" @change="inventoryName"><el-option v-for="size in wbOnlineSizes(creation.row)" :key="size.chrtID" :label="`${wbOnlineSizeLabel(size)} · ${size.chrtID}${wbOnlineMapping(creation.row,size)?'（已绑定）':''}`" :value="size.chrtID" :disabled="!!wbOnlineMapping(creation.row,size)"/></el-select></el-form-item><el-form-item label="本地库存产品名称" required><el-input v-model="creation.name" maxlength="200" show-word-limit/></el-form-item><div class="wb-grid creation-package"><el-form-item v-for="(label,key) in {length_cm:'包装长（cm）',width_cm:'包装宽（cm）',height_cm:'包装高（cm）',package_weight_g:'包装重量（g）'}" :key="key" :label="label" required><el-input-number v-model="creation[key]" :min="0.001" :precision="3" :controls="false" :placeholder="'填写'+label"/></el-form-item></div><p class="muted-text">包装资料仅保存到本地库存产品。保存后绑定所选 WB 规格，库存数量从零开始。</p></el-form><template #footer><el-button :disabled="busy" @click="creation.visible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!creationReady" @click="createInventory">创建并绑定</el-button></template></el-dialog>
    <el-dialog v-model="media.visible" title="编辑 WB 商品图片" width="680px" destroy-on-close><p>图片按填写顺序提交，每行一个 HTTPS 图片地址。提交会替换此商品的整组图片，请保留需要继续使用的图片。</p><el-input v-model="media.urls" type="textarea" :rows="8"/><template #footer><el-button @click="media.visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveMedia">保存图片</el-button></template></el-dialog>
    <el-dialog v-model="pricing.visible" title="更新 WB 价格" width="640px" destroy-on-close><el-form label-position="top"><el-form-item label="售价（店铺币种）"><el-input-number v-model="pricing.price" :min="0.01" :precision="2"/></el-form-item><el-form-item label="折扣（%）"><el-input-number v-model="pricing.discount" :min="0" :max="99" :precision="0"/></el-form-item></el-form><p v-if="pricing.task">任务已提交。需核对处理状态及商品级错误，尤其是价格隔离提示。</p><el-table v-if="pricing.result" :data="pricing.result.details?.data?.historyGoods||[]"><el-table-column prop="nmID" label="WB 商品"/><el-table-column prop="errorText" label="平台处理说明"/></el-table><p v-if="pricing.result">任务状态：{{pricing.result.task?.data?.status||'待平台确认'}}</p><template #footer><el-button @click="pricing.visible=false">关闭</el-button><el-button v-if="pricing.task" :loading="busy" @click="checkPrice">检查处理结果</el-button><el-button type="primary" :loading="busy" @click="savePrice">提交改价</el-button></template></el-dialog>
    <el-dialog v-model="stock.visible" title="更新 WB 仓库可售库存" width="640px" destroy-on-close><el-form label-position="top"><el-form-item label="WB 规格"><el-select v-model="stock.chrt" @change="loadStock"><el-option v-for="size in stock.row?.card.sizes||[]" :key="size.chrtID" :label="`${size.techSize||'通用'} · ${size.chrtID}`" :value="size.chrtID"/></el-select></el-form-item><p>本地可分配：{{stock.available}}　WB 当前可售：{{stock.current??'待核对'}}</p><el-form-item label="发布到 WB 的可售数量"><el-input-number v-model="stock.quantity" :min="0" :max="stock.available" :precision="0"/></el-form-item><p>本次只修改 WB 卖家仓可售量，不改变本地实物库存，也不会修改 Ozon 平台上的发布数量。</p></el-form><template #footer><el-button @click="stock.visible=false">取消</el-button><el-button :disabled="busy" @click="loadStock">刷新库存</el-button><el-button type="primary" :loading="busy" :disabled="stock.current===null" @click="saveStock">更新 WB 库存</el-button></template></el-dialog>
    <el-dialog v-model="errors.visible" title="WB 发布错误" width="min(900px,95vw)" destroy-on-close><el-table :data="Array.isArray(errors.rows)?errors.rows:[]" empty-text="WB 当前未返回发布错误"><el-table-column prop="vendorCode" label="商家货号"/><el-table-column label="处理说明"><template #default="{row}">{{Array.isArray(row.errors)?row.errors.join('；'):row.errorText||row.errors||'请核对 WB 后台'}}</template></el-table-column></el-table></el-dialog>
  </div>
